const e={133:{dayName:"Dia 133 — Segunda-feira",title:"Storytelling: Contando Experiências",focus:"Contar experiências com estrutura: contexto, ação e lição.",vocab:[{en:"Once",pt:"Certa vez"},{en:"Experience",pt:"Experiência"},{en:"Lesson",pt:"Lição"},{en:"Context",pt:"Contexto"},{en:"Lesson learned",pt:"Lição aprendida"},{en:"Challenge",pt:"Desafio"},{en:"Overcome",pt:"Superar"},{en:"Solution",pt:"Solução"},{en:"Advice",pt:"Conselho"},{en:"Share",pt:"Compartilhar"}],grammar:{title:"Estrutura de uma História",rule:"1) CONTEXTO no perfect: I have faced many challenges. 2) AÇÃO no past: Last year, one project failed. 3) LIÇÃO no perfect: Since then, I have planned better. 4) CONSELHO: My advice is...",table:[{form:"Contexto",example:"I have faced many challenges in my career.",pt:"Enfrentei muitos desafios na minha carreira."},{form:"Ação",example:"Last year, one project failed completely.",pt:"Ano passado, um projeto falhou completamente."},{form:"Lição",example:"Since then, I have planned each step carefully.",pt:"Desde então, planejo cada passo com cuidado."}]},reading:{title:"The Failed Project",text:"I have faced many challenges, but one taught me the most. Last year, my team started a project without a clear plan. We worked for months, but the client rejected the result. I have learned a huge lesson since then. Now, I always ask the right questions first. My advice: understand the problem before coding. Have you ever had a similar experience?",translation:"Enfrentei muitos desafios, mas um me ensinou mais. Ano passado, minha equipe começou um projeto sem um plano claro. Trabalhamos por meses, mas o cliente rejeitou o resultado. Aprendi uma lição enorme desde então. Agora, sempre faço as perguntas certas primeiro. Meu conselho: entenda o problema antes de programar. Você já teve uma experiência parecida?"},quiz:[{q:"Contexto de história:",options:["I have faced many challenges.","I face many challenges yesterday.","I facing challenges."],ans:"I have faced many challenges."},{q:"Ação no passado:",options:["Last year, the project failed.","Last year, the project has failed.","The project fails last year."],ans:"Last year, the project failed."},{q:"Lição:",options:["I have learned a huge lesson.","I learning a lesson.","I will learned it."],ans:"I have learned a huge lesson."}],chunks:[{en:"I have faced many challenges",pt:"enfrentei muitos desafios"},{en:"the client rejected the result",pt:"o cliente rejeitou o resultado"},{en:"understand before coding",pt:"entenda antes de programar"}],listeningScript:"Let me share an experience. Last year, my team started a project without a plan. The client rejected the result. Since then, I have asked better questions. My advice: understand before coding. Have you had a similar experience?",speakingPrompt:"Conte uma experiência: 'I have faced... Last year... Since then, I have... My advice is...'",lightReading:"Conference talks are stories: a hook (perfect), a struggle (past), a lesson (perfect), advice (imperative) — the 4-part structure works at any level.",journalPrompt:"Today is Day 133. I have shared a story in English.",tip:"DICA DE CONTAÇÃO: abra com uma frase perfeita ('I have never...'), depois o passado ('Once, I...'), feche com lição/advice. Nativos contam histórias assim — você também pode."},134:{dayName:"Dia 134 — Terça-feira",title:"Conquistas e Currículo (Achievements)",focus:"Falar de conquistas usando vocabulário de resultados.",vocab:[{en:"Achievement",pt:"Conquista"},{en:"Result",pt:"Resultado"},{en:"Improve",pt:"Melhorar"},{en:"Increase",pt:"Aumentar"},{en:"Reduce",pt:"Reduzir"},{en:"Save time",pt:"Economizar tempo"},{en:"Lead a team",pt:"Liderar uma equipe"},{en:"Deliver",pt:"Entregar"},{en:"Launch",pt:"Lançar"},{en:"Grow",pt:"Crescer"}],grammar:{title:"Conquistas com Números",rule:"Conquistas impactam quando trazem NÚMEROS: I have reduced costs by 20%. Estrutura: HAVE + verbo de ação + resultado numérico. Verbos-chave: improved, increased, reduced, saved, delivered, launched.",table:[{form:"Resultado",example:"I have reduced loading time by 30%.",pt:"Reduzi o tempo de carregamento em 30%."},{form:"Impacto",example:"I have increased user engagement by 15%.",pt:"Aumentei o engajamento dos usuários em 15%."},{form:"Entrega",example:"I have delivered 10 projects on time.",pt:"Entreguei 10 projetos no prazo."}]},reading:{title:"My Resume in Numbers",text:"Numbers make my resume powerful. In my last job, I have reduced costs by 20%. I have increased the team's productivity by 35%. I have launched three products successfully. I have led a team of five developers. I have saved the company many hours with automation. My manager has confirmed all these results. Achievements without numbers are just stories.",translation:"Números tornam meu currículo poderoso. No meu último emprego, reduzi custos em 20%. Aumentei a produtividade da equipe em 35%. Lancei três produtos com sucesso. Liderei uma equipe de cinco desenvolvedores. Economizei muitas horas da empresa com automação. Meu gerente confirmou todos esses resultados. Conquistas sem números são só histórias."},quiz:[{q:"Conquista com número:",options:["I have reduced costs by 20%.","I have reduced costs.","I reduced the costs maybe."],ans:"I have reduced costs by 20%."},{q:"Verbo para 'aumentar':",options:["increase","decrease","reduce"],ans:"increase"},{q:"Complete: 'I have ___ a team of five developers.'",options:["led","lead","leaded"],ans:"led"}],chunks:[{en:"I have reduced costs by 20%",pt:"reduzi custos em 20%"},{en:"I have launched three products",pt:"lancei três produtos"},{en:"I have led a team of five",pt:"liderei uma equipe de cinco"}],listeningScript:"My resume has numbers! I have reduced costs by 20%, increased productivity by 35%, and launched three products. I have led a team of five. Numbers make achievements real!",speakingPrompt:"Fale 5 conquistas com números: 'I have... by...% / I have delivered... / I have led...'",lightReading:"Resumes speak in numbers: 'Improved performance by 40%', 'Reduced bugs by 25%' — quantify every achievement; percentages are the universal language.",journalPrompt:"Today is Day 134. I have quantified my achievements.",tip:"DICA DE CURRÍCULO: transforme cada tarefa em resultado com número: 'I developed the API' → 'I have reduced API response time by 40%'. Números impressionam mais que adjetivos."},135:{dayName:"Dia 135 — Quarta-feira",title:"Revisão Total dos Perfects",focus:"Revisar simple e continuous lado a lado com prática guiada.",vocab:[{en:"Review",pt:"Revisão"},{en:"Combination",pt:"Combinação"},{en:"Compare",pt:"Comparar"},{en:"Whole picture",pt:"Quadro completo"},{en:"Structure",pt:"Estrutura"},{en:"Pattern",pt:"Padrão"},{en:"Practice",pt:"Prática"},{en:"Master",pt:"Dominar"},{en:"Convince",pt:"Convencer"},{en:"Prove",pt:"Provar"}],grammar:{title:"Perfects Lado a Lado",rule:"SIMPLE = resultado: I have fixed 3 bugs. CONTINUOUS = atividade: I have been fixing bugs all day. AMBOS aceitam for/since. Pergunta: How long have you been...? / Have you ever...? Os dois conectam passado ao presente.",table:[{form:"Simple",example:"I have fixed three bugs this week.",pt:"Corrigi três bugs esta semana."},{form:"Continuous",example:"I have been fixing bugs all day.",pt:"Venho corrigindo bugs o dia todo."},{form:"Perguntas",example:"Have you ever tried this? How long have you been coding?",pt:"Você já tentou isso? Há quanto tempo você programa?"}]},reading:{title:"The Perfect Team",text:"Today I reviewed everything. I have practiced the simple: 'I have completed the course.' And the continuous: 'I have been studying for months.' Have I mastered both? Almost. I have already done 30 exercises, and I haven't made a mistake yet. I have been improving my speed. The whole picture is clear now. Practice has proven its power.",translation:"Hoje revisei tudo. Pratiquei o simple: 'Completei o curso.' E o continuous: 'Venho estudando há meses.' Dominei os dois? Quase. Já fiz 30 exercícios, e ainda não cometi um erro. Venho melhorando minha velocidade. O quadro completo está claro agora. A prática provou seu poder."},quiz:[{q:"Resultado:",options:["I have completed the course.","I have been completing the course.","I completing the course."],ans:"I have completed the course."},{q:"Atividade:",options:["I have been studying for months.","I have studied. Done.","I am study."],ans:"I have been studying for months."},{q:"Complete: 'I ___ made a mistake yet.'",options:["haven't","hasn't","am not"],ans:"haven't"}],chunks:[{en:"I have completed the course",pt:"completei o curso"},{en:"I have been improving my speed",pt:"venho melhorando minha velocidade"},{en:"practice has proven its power",pt:"a prática provou seu poder"}],listeningScript:"Review time! I have practiced the simple and the continuous. I have done 30 exercises, and I haven't made a mistake yet. I have been improving every day. Practice wins!",speakingPrompt:"Compare os dois: 'I have...' (resultado) vs 'I have been...' (atividade). Faça 5 pares.",lightReading:"Bug reports mix both perfects: 'We have fixed the crash' (result) and 'We have been investigating all week' (process) — one ticket, two tenses.",journalPrompt:"Today is Day 135. I have reviewed both perfects.",tip:"DICA DE AUTOAVALIAÇÃO: escreva 3 resultados ('I have...') e 3 processos ('I have been...') sobre seu aprendizado. Se os dois saem rápido, você dominou o padrão."},136:{dayName:"Dia 136 — Quinta-feira",title:"Checkpoint B1 (Leitura e Compreensão)",focus:"Testar leitura com texto misto em todos os tempos.",vocab:[{en:"Checkpoint",pt:"Ponto de verificação"},{en:"Comprehension",pt:"Compreensão"},{en:"Mixed tenses",pt:"Tempos misturados"},{en:"Smooth",pt:"Fluido"},{en:"Accurate",pt:"Preciso"},{en:"Fluent",pt:"Fluente"},{en:"Level",pt:"Nível"},{en:"Target",pt:"Meta"},{en:"Progress",pt:"Progresso"},{en:"Assess",pt:"Avaliar"}],grammar:{title:"Leitura B1",rule:"Textos B1 misturam todos os tempos: present, past, future e perfects. Estratégia: sublinhe as âncoras de tempo. Cada âncora aponta o tempo certo. Leia primeiro o todo, depois os detalhes.",table:[{form:"Âncoras",example:"Yesterday → past. This week → perfect. Next month → future.",pt:"Ontem → passado. Esta semana → perfect. Mês que vem → futuro."},{form:"Perfect",example:"Since then, I have improved a lot.",pt:"Desde então, melhorei muito."},{form:"Futuro",example:"Next month, I will start interviews.",pt:"Mês que vem, começarei as entrevistas."}]},reading:{title:"The B1 Reader",text:"Today I tested my reading. Last week, I chose a developer blog. This week, I have read three full articles. Yesterday, I understood 80% without a dictionary. I have been surprised by my own progress. Since March, I have learned so many words. Next month, I will read technical documentation daily. My level is growing. Reading has become a pleasure.",translation:"Hoje testei minha leitura. Semana passada, escolhi um blog de desenvolvedores. Esta semana, li três artigos completos. Ontem, entendi 80% sem dicionário. Tenho me surpreendido com meu próprio progresso. Desde março, aprendi tantas palavras. Mês que vem, lerei documentação técnica diariamente. Meu nível está crescendo. Ler virou prazer."},quiz:[{q:"Qual tempo acompanha 'This week'?",options:["Present Perfect","Past Simple","Future"],ans:"Present Perfect"},{q:"Qual tempo acompanha 'Yesterday'?",options:["Past Simple","Present Perfect","Future"],ans:"Past Simple"},{q:"Complete: 'Next month, I ___ read documentation daily.'",options:["will","have","did"],ans:"will"}],chunks:[{en:"I have been surprised by my progress",pt:"tenho me surpreendido com meu progresso"},{en:"I have read three full articles",pt:"li três artigos completos"},{en:"reading has become a pleasure",pt:"ler virou prazer"}],listeningScript:"Level check! Last week, I chose a tech blog. This week, I have read three articles. Yesterday, I understood 80%. I have been surprised. Next month, I will read docs daily. Reading is a pleasure now!",speakingPrompt:"Avalie seu nível: 'Last week, I... This week, I have... Yesterday, I... Next month, I will...'",lightReading:"Set a reading target: 'Read 3 technical articles per week' — like code, language improves with daily input. Track it like a sprint.",journalPrompt:"Today is Day 136. I have passed my reading checkpoint.",tip:"DICA DE LEITURA B1: leia artigos de dev no Medium/Dev.to. Não traduza tudo: circule só 5 palavras por artigo. Se entender 80%, está no nível certo para subir."},137:{dayName:"Dia 137 — Sexta-feira",title:"Speaking Marathon (Descrevendo Projetos)",focus:"Falar de projetos de forma fluida por 3-5 minutos.",vocab:[{en:"Project",pt:"Projeto"},{en:"Objective",pt:"Objetivo"},{en:"Feature",pt:"Funcionalidade"},{en:"Challenge",pt:"Desafio"},{en:"Solution",pt:"Solução"},{en:"Technology",pt:"Tecnologia"},{en:"Result",pt:"Resultado"},{en:"Lessons",pt:"Lições"},{en:"Timeline",pt:"Linha do tempo"},{en:"Scope",pt:"Escopo"}],grammar:{title:"Estrutura para Falar de Projetos",rule:"O que é (present): This is a tool for... Propósito (to + verbo): I built it to solve... Processo (past): First, I... Resultado (perfect): Since then, I have... Lição: I have learned that...",table:[{form:"O que é",example:"This is a budget app for students.",pt:"Este é um app de orçamento para estudantes."},{form:"Propósito",example:"I built it to control monthly expenses.",pt:"Construí para controlar gastos mensais."},{form:"Resultado",example:"My friends have used it daily since May.",pt:"Meus amigos o usam diariamente desde maio."}]},reading:{title:"My Portfolio Speech",text:"Let me present my best project. This is a study tracker I built last year. I built it to help students organize their routine. First, I designed the interface. Then, I coded the features. The biggest challenge was the notifications. Finally, I solved it with a simple queue. Since then, I have improved it twice. I have learned that small tools solve big problems.",translation:"Vou apresentar meu melhor projeto. Este é um rastreador de estudos que construí ano passado. Construí para ajudar estudantes a organizarem sua rotina. Primeiro, desenhei a interface. Depois, codei as funcionalidades. O maior desafio foram as notificações. Finalmente, resolvi com uma fila simples. Desde então, melhorei duas vezes. Aprendi que pequenas ferramentas resolvem grandes problemas."},quiz:[{q:"Apresentando o projeto:",options:["This is a study tracker.","This was a study tracker yesterday.","This is being study."],ans:"This is a study tracker."},{q:"Propósito:",options:["I built it to help students.","I built it for help students.","I build it to helping."],ans:"I built it to help students."},{q:"Chamada de atenção:",options:["The biggest challenge was the notifications.","The challenge are notifications.","Challenges is notifications."],ans:"The biggest challenge was the notifications."}],chunks:[{en:"this is a study tracker",pt:"este é um rastreador de estudos"},{en:"I built it to help students",pt:"construí para ajudar estudantes"},{en:"I have learned that small tools solve big problems",pt:"aprendi que pequenas ferramentas resolvem grandes problemas"}],listeningScript:"My best project: a study tracker. I built it last year to help students. First, the interface. Then, the features. The challenge? Notifications. I solved them with a queue. I have improved it twice since then.",speakingPrompt:"Apresente um projeto em 3 minutos: 'This is... I built it to... First... The challenge was... Since then, I have...'",lightReading:"Portfolio presentations follow the same flow as talks: what (present), why (purpose), how (past), outcome (perfect), lesson (present perfect) — practice your script daily.",journalPrompt:"Today is Day 137. I have presented a project in English.",tip:"DICA DE MARATONA: fale 3 minutos CONTÍNUOS sobre qualquer projeto. Se travar, repita a última frase em vez de parar. Fluência = capacidade de seguir em frente mesmo com erros."},138:{dayName:"Dia 138 — Sábado",title:"Consolidação da Semana 20 + TESTE DE SÁBADO 20",focus:"Testar storytelling, conquistas e revisão B1.",vocab:[{en:"Story",pt:"História"},{en:"Achievement",pt:"Conquista"},{en:"Review",pt:"Revisão"},{en:"Level",pt:"Nível"},{en:"Confidence",pt:"Confiança"},{en:"Interview",pt:"Entrevista"},{en:"Portfolio",pt:"Portfólio"},{en:"Growth",pt:"Crescimento"},{en:"Milestone",pt:"Marco"},{en:"Future",pt:"Futuro"}],grammar:{title:"Resumo da Semana 20",rule:"Histórias: perfect (contexto) → past (ação) → perfect (lição). Conquistas: verbo de ação + número (reduced by 20%). Revisão dos perfects: simple (resultado) e continuous (atividade).",table:[{form:"Contexto",example:"I have faced many challenges.",pt:"Enfrentei muitos desafios."},{form:"Ação",example:"Last year, one project failed.",pt:"Ano passado, um projeto falhou."},{form:"Conquista",example:"I have reduced costs by 20%.",pt:"Reduzi custos em 20%."}]},reading:{title:"The Progress Review",text:"Today is my weekly review. I have practiced storytelling all week. I have shared my experiences: the challenge, the action, and the lesson. I have also practiced talking about achievements with numbers. Yesterday, I presented my portfolio speech. Since then, I have felt more confident. Next week, I will start the conditionals. I have built a solid routine. Consistency has become my superpower.",translation:"Hoje é minha revisão semanal. Pratiquei storytelling a semana toda. Compartilhei minhas experiências: o desafio, a ação e a lição. Também pratiquei falar de conquistas com números. Ontem, apresentei meu discurso de portfólio. Desde então, me sinto mais confiante. Semana que vem, começarei os condicionais. Construí uma rotina sólida. A constância virou meu superpoder."},quiz:[{q:"Complete: 'I have ___ costs by 20%.'",options:["reduced","reduce","reducing"],ans:"reduced"},{q:"Complete: 'Since then, I have ___ more confident.'",options:["felt","feel","feeling"],ans:"felt"},{q:"Complete: 'Next week, I ___ start the conditionals.'",options:["will","have","did"],ans:"will"}],chunks:[{en:"I have practiced storytelling",pt:"pratiquei storytelling"},{en:"since then, I have felt confident",pt:"desde então, me sinto confiante"},{en:"consistency has become my superpower",pt:"a constância virou meu superpoder"}],listeningScript:"Weekly review! I have practiced storytelling and achievements. Yesterday, I presented my portfolio speech. Since then, I have felt confident. Next week: conditionals. Consistency wins!",speakingPrompt:"Grave seu Teste de Sábado: 'This week, I have... Yesterday, I... Since then, I have... Next week, I will...'",lightReading:"Great storytellers in tech follow the script: hook with perfect, struggle in past, breakthrough, lesson. Watch any conference talk and spot the three parts.",journalPrompt:"Today is Day 138. I have passed my Saturday Test 20!",tip:"DICA DE SEMANA: salve suas 2 melhores histórias (uma de sucesso, uma de fracasso que virou lição). Essas duas histórias servem para qualquer entrevista de emprego."},139:{dayName:"Dia 139 — Domingo",title:"Revisão da Semana 20 & Imersão Leve",focus:"Consolidar storytelling com leitura leve de histórias reais.",vocab:[{en:"True story",pt:"História real"},{en:"Hero",pt:"Herói"},{en:"Journey",pt:"Jornada"},{en:"Success story",pt:"História de sucesso"},{en:"Failure",pt:"Fracasso"},{en:"Comeback",pt:"Retorno / Reviravolta"},{en:"Inspiration",pt:"Inspiração"},{en:"Motivation",pt:"Motivação"},{en:"Profile",pt:"Perfil"},{en:"Lesson",pt:"Lição"}],grammar:{title:"Checkpoint 139 — As Duas Histórias",rule:"Tenha prontas suas duas histórias: sucesso ('I have achieved...') e superação ('I have failed, but I have learned...'). Sucesso = perfect + números. Superação = perfect (contexto) → past (ação) → perfect (lição).",table:[{form:"Sucesso",example:"I have increased sales by 25% in my last job.",pt:"Aumentei as vendas em 25% no meu último emprego."},{form:"Superação",example:"My first app failed, but I have grown since then.",pt:"Meu primeiro app falhou, mas cresci desde então."},{form:"Inspiração",example:"That failure has inspired my best work.",pt:"Aquele fracasso inspirou meu melhor trabalho."}]},reading:{title:"Two Stories to Tell",text:"Everyone remembers a good story. My success story: last year, I improved a slow system. The result? Load time has reduced by 50%. My comeback story: in 2023, my first app failed. I have never forgotten that day. Since then, I have studied harder and planned better. That failure has inspired me. Have you prepared your two stories?",translation:"Todos lembram de uma boa história. Minha história de sucesso: ano passado, melhorei um sistema lento. O resultado? O tempo de carregamento reduziu 50%. Minha história de superação: em 2023, meu primeiro app falhou. Nunca esqueci aquele dia. Desde então, estudei mais e planejei melhor. Aquele fracasso me inspirou. Você preparou suas duas histórias?"},quiz:[{q:"Complete: 'Load time ___ reduced by 50%.'",options:["has","have","is having"],ans:"has"},{q:"Complete: 'That failure has ___ me.'",options:["inspired","inspire","inspiring"],ans:"inspired"},{q:"Complete: 'Since then, I have studied harder and ___ better.'",options:["planned","plan","planning"],ans:"planned"}],chunks:[{en:"I have improved a slow system",pt:"melhorei um sistema lento"},{en:"my first app failed",pt:"meu primeiro app falhou"},{en:"that failure has inspired me",pt:"aquele fracasso me inspirou"}],listeningScript:"Two stories, one lesson. Success: I improved a system and reduced load time by 50%. Comeback: in 2023, my first app failed. I have never forgotten. Since then, I have planned better. Have you prepared yours?",speakingPrompt:"Conte suas duas histórias: a de sucesso e a de superação. Use perfect + past + perfect.",lightReading:"Company 'about' pages are collections of two stories: the founding struggle (past) and the growth since (perfect) — stories sell better than stats.",journalPrompt:"Today is Day 139. I have prepared my two stories.",tip:"DICA DE DOMINGO: escreva suas duas histórias em 5 frases cada. Revise na segunda. Repita até sair sem olhar. São suas 'armas de conversa' para sempre."},140:{dayName:"Dia 140 — Segunda-feira",title:"First Conditional (If + Present, Will)",focus:"Falar de situações reais e prováveis no futuro.",vocab:[{en:"If",pt:"Se"},{en:"Condition",pt:"Condição"},{en:"Result",pt:"Resultado"},{en:"Real situation",pt:"Situação real"},{en:"Probably",pt:"Provavelmente"},{en:"Pass",pt:"Passar"},{en:"Work",pt:"Funcionar"},{en:"Fail",pt:"Falhar"},{en:"Try",pt:"Tentar"},{en:"Deal with",pt:"Lidar com"}],grammar:{title:"First Conditional",rule:"IF + presente, WILL + verbo base: If I study, I will pass. A condição é real e provável. NUNCA use will dentro da frase 'if'. Ordem livre: I will pass if I study.",table:[{form:"Condição real",example:"If I study daily, I will improve.",pt:"Se eu estudar diariamente, vou melhorar."},{form:"Negativa",example:"If you don't test, bugs will appear.",pt:"Se você não testar, bugs aparecerão."},{form:"Ordem invertida",example:"You will pass if you practice.",pt:"Você vai passar se praticar."}]},reading:{title:"The Exam Plan",text:"My English exam is next month. If I study every day, I will pass easily. If I don't review the conditionals, I will make mistakes. If the listening is fast, I will listen twice. My plan is simple: if I follow it, I will succeed. And if I succeed, I will celebrate! Do you also have a plan?",translation:"Meu exame de inglês é mês que vem. Se eu estudar todos os dias, passarei facilmente. Se eu não revisar os condicionais, cometerei erros. Se o listening for rápido, ouvirei duas vezes. Meu plano é simples: se eu segui-lo, terei sucesso. E se eu tiver sucesso, vou comemorar! Você também tem um plano?"},quiz:[{q:"Estrutura correta:",options:["If I study, I will pass.","If I will study, I pass.","If I study, I pass will."],ans:"If I study, I will pass."},{q:"Complete: 'If I don't test, bugs ___ appear.'",options:["will","would","won't"],ans:"will"},{q:"Ordem invertida:",options:["You will pass if you practice.","If you will practice, you pass.","Practice if you will pass."],ans:"You will pass if you practice."}],chunks:[{en:"if I study daily, I will improve",pt:"se eu estudar diariamente, vou melhorar"},{en:"if you don't test, bugs will appear",pt:"se você não testar, bugs aparecerão"},{en:"you will pass if you practice",pt:"você vai passar se praticar"}],listeningScript:"My exam plan! If I study every day, I will pass. If I don't review, I will make mistakes. If the listening is fast, I will listen twice. If I succeed, I will celebrate!",speakingPrompt:"Faça 5 previsões reais: 'If I..., I will...' sobre estudos, trabalho e vida.",lightReading:"Docs use real conditionals: 'If you install the package, it will work', 'If the port is busy, the app will fail' — technical writing is full of if/will.",journalPrompt:"Today is Day 140. I have learned the First Conditional.",tip:"DICA DE OURO: nunca diga 'If I will'. A frase 'if' sempre usa presente. Esse é o erro que mais entrega não-nativos em exames. Grave: IF + PRESENT, WILL + VERBO."},141:{dayName:"Dia 141 — Terça-feira",title:"When, As Soon As, Unless",focus:"Expandir condicionais com quando, assim que e a menos que.",vocab:[{en:"When",pt:"Quando"},{en:"As soon as",pt:"Assim que"},{en:"Unless",pt:"A menos que"},{en:"Until",pt:"Até que"},{en:"Providing that",pt:"Desde que"},{en:"In case",pt:"Caso"},{en:"Immediately",pt:"Imediatamente"},{en:"Later",pt:"Mais tarde"},{en:"Warning",pt:"Aviso"},{en:"Promise",pt:"Promessa"}],grammar:{title:"Variações do First Conditional",rule:"WHEN + presente = certeza: When I arrive, I will call. AS SOON AS = imediato: As soon as it finishes, we will ship. UNLESS = se não: Unless you try, you won't learn (= If you don't try). IN CASE = precaução: I will take notes in case I forget.",table:[{form:"Certeza",example:"When the code compiles, I will commit.",pt:"Quando o código compilar, farei commit."},{form:"Imediato",example:"As soon as the tests pass, we will deploy.",pt:"Assim que os testes passarem, implantaremos."},{form:"A menos que",example:"Unless you try, you won't learn.",pt:"A menos que você tente, não vai aprender."}]},reading:{title:"The Launch Day",text:"We have a launch checklist. When the manager arrives, we will start. As soon as the tests pass, we will deploy. Unless the server is down, everything will be fine. In case something fails, we have a backup. Until the launch ends, I will stay online. When it is over, we will celebrate!",translation:"Temos uma lista de lançamento. Quando o gerente chegar, começaremos. Assim que os testes passarem, implantaremos. A menos que o servidor caia, tudo ficará bem. Caso algo falhe, temos um backup. Até o lançamento terminar, ficarei online. Quando acabar, vamos comemorar!"},quiz:[{q:"Complete: '___ you try, you won't learn.'",options:["Unless","If","When"],ans:"Unless"},{q:"Complete: '___ as the tests pass, we will deploy.'",options:["As soon","Now","Until"],ans:"As soon"},{q:"Complete: 'When the manager ___ we will start.'",options:["arrives","will arrive","arrive"],ans:"arrives"}],chunks:[{en:"as soon as the tests pass, we will deploy",pt:"assim que os testes passarem, implantaremos"},{en:"unless you try, you won't learn",pt:"a menos que você tente, não vai aprender"},{en:"in case something fails, we have a backup",pt:"caso algo falhe, temos um backup"}],listeningScript:"Launch checklist! When the manager arrives, we start. As soon as the tests pass, we deploy. Unless the server is down, all good. In case of failure, backup. When it ends, we celebrate!",speakingPrompt:"Use as variações: 'When I... As soon as I... Unless I... In case...'",lightReading:"CI/CD pipelines are conditionals in practice: 'When code is pushed, tests run. Unless tests pass, no deploy' — infrastructure speaks first conditional.",journalPrompt:"Today is Day 141. I have learned when, as soon as and unless.",tip:"DICA DE CONVERSÃO: UNLESS já contém o 'não'. 'Unless you try' = 'If you don't try'. Nunca diga 'unless you don't' — é dupla negação."},142:{dayName:"Dia 142 — Quarta-feira",title:"First Conditional com Modais (Can, Must, Should)",focus:"Combinar condicionais com verbos modais.",vocab:[{en:"Can",pt:"Pode (capacidade)"},{en:"Must",pt:"Deve (obrigação)"},{en:"Should",pt:"Deveria"},{en:"Permission",pt:"Permissão"},{en:"Obligation",pt:"Obrigação"},{en:"Advice",pt:"Conselho"},{en:"Request",pt:"Pedido"},{en:"Approval",pt:"Aprovação"},{en:"Access",pt:"Acesso"},{en:"Rule",pt:"Regra"}],grammar:{title:"If + Presente, Variedade de Resultados",rule:"O resultado pode usar qualquer modal: If you subscribe, you CAN access (permissão). If it breaks, you MUST fix it (obrigação). If you want, you SHOULD ask (conselho). O 'if' continua no presente.",table:[{form:"Permissão",example:"If you pay, you can access the course.",pt:"Se você pagar, pode acessar o curso."},{form:"Obrigação",example:"If the server fails, we must restart it.",pt:"Se o servidor falhar, devemos reiniciá-lo."},{form:"Conselho",example:"If you have doubts, you should ask.",pt:"Se você tiver dúvidas, deveria perguntar."}]},reading:{title:"Team Rules",text:"Our team has clear rules. If you need access, you must request it. If you finish early, you can leave. If you find a bug, you should document it. If you want a promotion, you must deliver results. If the client calls, we should answer quickly. These rules make things clear: if everyone follows them, we will succeed.",translation:"Nossa equipe tem regras claras. Se você precisar de acesso, deve solicitá-lo. Se terminar cedo, pode ir embora. Se encontrar um bug, deve documentá-lo. Se quiser uma promoção, deve entregar resultados. Se o cliente ligar, devemos responder rápido. Essas regras deixam tudo claro: se todos as seguirem, teremos sucesso."},quiz:[{q:"Permissão:",options:["If you pay, you can access.","If you pay, you must access.","If you will pay, you can."],ans:"If you pay, you can access."},{q:"Obrigação:",options:["If the server fails, we must restart it.","If the server fails, we restarting.","If fails the server, we must."],ans:"If the server fails, we must restart it."},{q:"Conselho:",options:["If you have doubts, you should ask.","If you have doubts, you will ask maybe.","If you doubts, ask you should."],ans:"If you have doubts, you should ask."}],chunks:[{en:"if you pay, you can access",pt:"se você pagar, pode acessar"},{en:"if the server fails, we must restart",pt:"se o servidor falhar, devemos reiniciar"},{en:"if you have doubts, you should ask",pt:"se tiver dúvidas, deveria perguntar"}],listeningScript:"Team rules! If you need access, you must request it. If you finish early, you can leave. If you find a bug, document it. If everyone follows the rules, we will succeed!",speakingPrompt:"Crie regras do seu time/estudos: 'If I..., I can/must/should...'",lightReading:"Access control docs are full of modal conditionals: 'If you are an admin, you can deploy. If you are a member, you must request approval' — permissions as grammar.",journalPrompt:"Today is Day 142. I have learned conditionals with modals.",tip:"DICA DE SISTEMA: escolha o modal pelo INTENT: can = permissão/habilidade, must = obrigação, should = conselho. A frase 'if' só muda a condição; o modal muda a atitude."},143:{dayName:"Dia 143 — Quinta-feira",title:"Erros Clássicos do First Conditional",focus:"Corrigir os 5 erros mais comuns do first conditional.",vocab:[{en:"Mistake",pt:"Erro"},{en:"Common",pt:"Comum"},{en:"Correct",pt:"Correto"},{en:"Fix",pt:"Corrigir"},{en:"Avoid",pt:"Evitar"},{en:"Rule",pt:"Regra"},{en:"Trap",pt:"Armadilha"},{en:"Careful",pt:"Cuidadoso"},{en:"Accurate",pt:"Preciso"},{en:"Check",pt:"Conferir"}],grammar:{title:"Os 5 Erros Famosos",rule:"1) 'If I will' → NUNCA: If I go, I will call. 2) 'If you would' → If you come... 3) Dupla negativa com unless: unless you don't → unless you. 4) Esquecer o -s na 3ª pessoa: If she comes... 5) Will na frase 'when': When it finishes...",table:[{form:"Erro → Correto",example:"If I will go → If I go",pt:"Se eu for (nunca 'will' no if)"},{form:"Erro → Correto",example:"Unless you don't try → Unless you try",pt:"A menos que você tente"},{form:"Erro → Correto",example:"If she come → If she comes",pt:"Se ela vier (3ª pessoa -s)"}]},reading:{title:"The Error Hunt",text:"Today I hunted for conditional errors in my old notes. I found: 'If I will have time' — wrong! The correct form: If I have time, I will help. 'Unless you don't practice' — wrong! Unless you practice, you won't improve. 'When she arrive' — wrong! When she arrives, we will start. If I review my notes, I will avoid these traps. Good hunt!",translation:"Hoje caçei erros de condicionais nas minhas anotações antigas. Achei: 'If I will have time' — errado! A forma correta: If I have time, I will help. 'Unless you don't practice' — errado! Unless you practice, you won't improve. 'When she arrive' — errado! When she arrives, we will start. Se eu revisar minhas notas, evitarei essas armadilhas. Boa caçada!"},quiz:[{q:"Correto:",options:["If I have time, I will help.","If I will have time, I help.","If I have time, I will helping."],ans:"If I have time, I will help."},{q:"Correto:",options:["Unless you practice, you won't improve.","Unless you don't practice, you won't improve.","Unless you will practice, you improve."],ans:"Unless you practice, you won't improve."},{q:"Complete: 'When she ___ we will start.'",options:["arrives","arrive","will arrive"],ans:"arrives"}],chunks:[{en:"if I have time, I will help",pt:"se eu tiver tempo, vou ajudar"},{en:"unless you practice, you won't improve",pt:"a menos que pratique, não vai melhorar"},{en:"when she arrives, we will start",pt:"quando ela chegar, começaremos"}],listeningScript:"Error hunt! 'If I will have time'? Wrong! Say: If I have time, I will help. 'Unless you don't practice'? Wrong! Say: Unless you practice. 'When she arrive'? Wrong! Say: When she arrives. Traps avoided!",speakingPrompt:"Conte erros que já cometeu: 'I used to say... Now I say... If I had known...' — e pratique as formas corretas.",lightReading:"Error logs are honest: 'If the config is wrong, the app will crash' — docs show the correct pattern; your job is to avoid the wrong one.",journalPrompt:"Today is Day 143. I have fixed my conditional mistakes.",tip:"DICA DE AUTOAVALIAÇÃO: grave-se falando 2 minutos em condicionais. Depois, ouça e caça erros como os de hoje. Ouvir a si mesmo é o professor mais barato e mais eficaz."},144:{dayName:"Dia 144 — Sexta-feira",title:"First Conditional no Mundo Tech",focus:"Aplicar condicionais reais em cenários de software.",vocab:[{en:"Deploy",pt:"Implantar"},{en:"Crash",pt:"Travar / Quebrar"},{en:"Retry",pt:"Tentar de novo"},{en:"Timeout",pt:"Tempo esgotado"},{en:"Backup",pt:"Backup"},{en:"Restore",pt:"Restaurar"},{en:"Load",pt:"Carregar"},{en:"Validate",pt:"Validar"},{en:"Notify",pt:"Notificar"},{en:"Retry logic",pt:"Lógica de nova tentativa"}],grammar:{title:"Condicionais em Sistemas",rule:"Sistemas são máquinas de condicionais: If the request times out, we will retry. If validation fails, we will notify the user. If the backup is old, we will restore it. Pergunte: 'What happens if...?' é a pergunta de engenheiro.",table:[{form:"Sistema",example:"If the request times out, we will retry.",pt:"Se a requisição expirar, tentaremos de novo."},{form:"Validação",example:"If validation fails, the user will see an error.",pt:"Se a validação falhar, o usuário verá um erro."},{form:"Pergunta de engenheiro",example:"What will happen if the database goes down?",pt:"O que acontecerá se o banco cair?"}]},reading:{title:"Designing for Failure",text:"Good systems plan for failure. If the API times out, we will retry three times. If the database is down, we will show a friendly message. If the payment fails, the user will receive a notification. As soon as we detect a problem, we will log it. Unless we test these paths, bugs will appear in production. Engineers always ask: what will happen if...?",translation:"Bons sistemas planejam a falha. Se a API expirar, tentaremos três vezes. Se o banco cair, mostraremos uma mensagem amigável. Se o pagamento falhar, o usuário receberá uma notificação. Assim que detectarmos um problema, registraremos. A menos que testemos esses caminhos, bugs aparecerão em produção. Engenheiros sempre perguntam: o que acontecerá se...?"},quiz:[{q:"Complete: 'If the request times out, we ___ retry.'",options:["will","would","won't"],ans:"will"},{q:"Complete: 'If the payment fails, the user ___ a notification.'",options:["will receive","would receive","receives will"],ans:"will receive"},{q:"Complete: '___ we test these paths, bugs will appear.'",options:["Unless","If","So"],ans:"Unless"}],chunks:[{en:"if the request times out, we will retry",pt:"se a requisição expirar, tentaremos de novo"},{en:"what will happen if the database goes down?",pt:"o que acontecerá se o banco cair?"},{en:"unless we test, bugs will appear",pt:"a menos que testemos, bugs aparecerão"}],listeningScript:"Design for failure! If the API times out, retry. If the database is down, show a friendly message. As soon as we detect a problem, log it. Unless we test, bugs will appear!",speakingPrompt:"Pense num sistema e explique: 'If... will... As soon as... Unless...'",lightReading:"Resilience engineering is first conditional: 'If X happens, we do Y' — the whole field is describing conditional responses to failures.",journalPrompt:"Today is Day 144. I have applied conditionals to systems.",tip:"DICA DE ENTREVISTA TÉCNICA: ao explicar sistemas, use 'What happens if...?' para mostrar pensamento crítico. Recrutadores adoram candidatos que desenham cenários de falha em condicionais."},145:{dayName:"Dia 145 — Sábado",title:"Consolidação da Semana 21 + TESTE DE SÁBADO 21",focus:"Testar o first conditional completo e suas variações.",vocab:[{en:"Condition",pt:"Condição"},{en:"Consequence",pt:"Consequência"},{en:"Possible",pt:"Possível"},{en:"Prediction",pt:"Previsão"},{en:"Plan",pt:"Plano"},{en:"Warning",pt:"Aviso"},{en:"Promise",pt:"Promessa"},{en:"Offer",pt:"Oferta"},{en:"Decision",pt:"Decisão"},{en:"Action",pt:"Ação"}],grammar:{title:"Resumo da Semana 21",rule:"First Conditional: IF + presente, WILL/ modais + verbo. Quando: When + presente (certeza). As soon as: imediato. Unless = if... not. In case = precaução. Nunca 'will' dentro da frase com if/when.",table:[{form:"Condição real",example:"If I get the job, I will move.",pt:"Se eu conseguir o emprego, vou me mudar."},{form:"Modal",example:"If you are hired, you must sign.",pt:"Se você for contratado, deve assinar."},{form:"Certeza",example:"When I finish, I will tell you.",pt:"Quando eu terminar, vou te contar."}]},reading:{title:"The Job Offer",text:"I have great news: I received a job offer! If I accept it, I will move to a new city. When I arrive, I will look for a small apartment. As soon as I sign the contract, I will start. Unless the salary is low, I will accept immediately. If you need me, I will keep my current number. In case I change it, I will notify everyone. Decisions are easier with clear conditions!",translation:"Tenho ótimas notícias: recebi uma proposta de emprego! Se eu aceitá-la, vou me mudar para uma nova cidade. Quando eu chegar, procurarei um apartamento pequeno. Assim que assinar o contrato, começarei. A menos que o salário seja baixo, aceitarei imediatamente. Se você precisar de mim, manterei meu número atual. Caso eu o mude, avisarei a todos. Decisões são mais fáceis com condições claras!"},quiz:[{q:"Complete: 'If I ___ it, I will move.'",options:["accept","will accept","accepted"],ans:"accept"},{q:"Complete: '___ I sign the contract, I will start.'",options:["As soon as","Unless","Although"],ans:"As soon as"},{q:"Complete: '___ the salary is low, I will accept.'",options:["Unless","If","When"],ans:"Unless"}],chunks:[{en:"if I accept it, I will move",pt:"se eu aceitar, vou me mudar"},{en:"as soon as I sign, I will start",pt:"assim que assinar, começarei"},{en:"unless the salary is low",pt:"a menos que o salário seja baixo"}],listeningScript:"Big news: a job offer! If I accept, I will move. When I arrive, I will find an apartment. As soon as I sign, I will start. Unless the salary is low, I accept!",speakingPrompt:"Grave seu Teste de Sábado: 'If I..., I will... When I..., I will... As soon as..., I will... Unless..., I will...'",lightReading:"Negotiations are conditional conversations: 'If you increase the offer, I will sign today' — first conditional is negotiation language.",journalPrompt:"Today is Day 145. I have passed my Saturday Test 21!",tip:"DICA DE NEGOCIAÇÃO: a frase 'If you... I will...' é a mais poderosa de negociações. Use-a com educação: 'If the start date is flexible, I will accept today.'"},146:{dayName:"Dia 146 — Domingo",title:"Revisão da Semana 21 & Imersão Leve",focus:"Revisar condicionais reais com conteúdo leve.",vocab:[{en:"Brainstorm",pt:"Tempestade de ideias"},{en:"Idea",pt:"Ideia"},{en:"Plan",pt:"Plano"},{en:"Game",pt:"Jogo"},{en:"Strategy",pt:"Estratégia"},{en:"Review",pt:"Revisão"},{en:"Relax",pt:"Relaxar"},{en:"Predict",pt:"Prever"},{en:"Result",pt:"Resultado"},{en:"Rest",pt:"Descanso"}],grammar:{title:"Checkpoint 146 — Condicionais Reais",rule:"Você já prevê resultados em inglês: se X acontecer, Y acontecerá. Essa habilidade é usada em reuniões, planejamento e conversas do dia a dia. Quando/se/assim que = seu repertório de futuro.",table:[{form:"Planejamento",example:"If the market grows, we will hire more.",pt:"Se o mercado crescer, contrataremos mais."},{form:"Jogo",example:"If I win this match, I will buy a new mouse.",pt:"Se eu vencer esta partida, comprarei um mouse novo."},{form:"Previsão",example:"As soon as I rest, I will study again.",pt:"Assim que eu descansar, estudarei de novo."}]},reading:{title:"Sunday Strategy",text:"Today I planned my week. If I wake up early, I will study before work. When I have free time, I will review the conditionals. As soon as I finish my tasks, I will watch a game. If my team plays well, I will celebrate. Unless I rest enough, I will be tired. Sunday planning makes the week smooth.",translation:"Hoje planejei minha semana. Se eu acordar cedo, estudarei antes do trabalho. Quando tiver tempo livre, revisarei os condicionais. Assim que terminar minhas tarefas, assistirei a um jogo. Se meu time jogar bem, vou comemorar. A menos que eu descanse o suficiente, ficarei cansado. Planejar no domingo deixa a semana fluida."},quiz:[{q:"Complete: 'If I wake up early, I ___ study.'",options:["will","would","do"],ans:"will"},{q:"Complete: '___ I finish my tasks, I will watch a game.'",options:["As soon as","Unless","Though"],ans:"As soon as"},{q:"Complete: '___ I rest enough, I will be tired.'",options:["Unless","If","When"],ans:"Unless"}],chunks:[{en:"if I wake up early, I will study",pt:"se eu acordar cedo, estudarei"},{en:"as soon as I finish, I will watch",pt:"assim que terminar, assistirei"},{en:"unless I rest, I will be tired",pt:"a menos que descanse, ficarei cansado"}],listeningScript:"Sunday strategy! If I wake up early, I study. When I have free time, I review. As soon as I finish, I relax. Unless I rest, I will be tired. Plan your week!",speakingPrompt:"Planeje sua semana em condicionais: 'If I... I will... When I... As soon as... Unless...'",lightReading:"Coaches predict outcomes: 'If you practice this way, you will improve' — conditional planning is the language of strategy in every field.",journalPrompt:"Today is Day 146. I have planned my week with conditionals.",tip:"DICA DE DOMINGO: use o domingo para prever a semana em inglês: 5 frases com 'If... I will...' Isso transforma o planejamento em prática de speaking."},147:{dayName:"Dia 147 — Segunda-feira",title:"Second Conditional (If + Past, Would)",focus:"Falar de situações hipotéticas e imaginárias.",vocab:[{en:"Hypothetical",pt:"Hipotético"},{en:"Imaginary",pt:"Imaginário"},{en:"Would",pt:"Faria"},{en:"Dream",pt:"Sonho"},{en:"If I had",pt:"Se eu tivesse"},{en:"If I knew",pt:"Se eu soubesse"},{en:"Possible",pt:"Possível"},{en:"Unreal",pt:"Irreal"},{en:"Wish",pt:"Desejo"},{en:"Reality",pt:"Realidade"}],grammar:{title:"Second Conditional",rule:"IF + passado, WOULD + verbo base: If I had more time, I would study. Situação IMAGINÁRIA ou improvável. 'If I were' para todos (subjuntivo). Contração: would → 'd (I'd).",table:[{form:"Imaginário",example:"If I had a million dollars, I would travel.",pt:"Se eu tivesse um milhão de dólares, viajaria."},{form:"Conselho",example:"If I were you, I would practice daily.",pt:"Se eu fosse você, praticaria diariamente."},{form:"Contração",example:"I'd learn another language if I could.",pt:"Eu aprenderia outro idioma se pudesse."}]},reading:{title:"If I Had More Time",text:"If I had more time, I would build a complete open-source project. If I were a manager, I would reduce meetings. If I knew how to design, I would create beautiful interfaces. I would contribute to more communities if I could. These dreams keep me motivated. And if I stopped dreaming, I would stop growing. Reality can follow dreams.",translation:"Se eu tivesse mais tempo, construiria um projeto open-source completo. Se eu fosse gerente, reduziria reuniões. Se eu soubesse desenhar, criaria interfaces bonitas. Contribuiria para mais comunidades se pudesse. Esses sonhos me mantêm motivado. E se eu parasse de sonhar, pararia de crescer. A realidade pode seguir os sonhos."},quiz:[{q:"Hipotético:",options:["If I had more time, I would study.","If I have more time, I will study.","If I will have time, I study."],ans:"If I had more time, I would study."},{q:"Conselho:",options:["If I were you, I would practice.","If I was you, I practice.","If I am you, I would."],ans:"If I were you, I would practice."},{q:"Contração de 'I would':",options:["I'd","I'would","Id"],ans:"I'd"}],chunks:[{en:"if I had more time, I would build",pt:"se eu tivesse mais tempo, construiria"},{en:"if I were you, I would practice",pt:"se eu fosse você, praticaria"},{en:"if I stopped dreaming, I would stop growing",pt:"se eu parasse de sonhar, pararia de crescer"}],listeningScript:"Dream scenario! If I had more time, I would build an open-source project. If I were a manager, I would reduce meetings. If I could, I would contribute more. Dreams keep me growing!",speakingPrompt:"Fale de sonhos: 'If I had... I would... If I were... I would... I'd...'",lightReading:"Roadmaps dream in second conditional: 'If we had more engineers, we would ship faster' — hypothetical planning is strategy language.",journalPrompt:"Today is Day 147. I have learned the Second Conditional.",tip:"DICA DE SUBJUNTIVO: 'If I were' (não 'was') para I/he/she/it. É o subjuntivo: If I were rich, if she were here. Em conversas informais 'was' aparece, mas em provas e entrevistas use 'were'."},148:{dayName:"Dia 148 — Terça-feira",title:"If I Were You (Conselhos Hipotéticos)",focus:"Dar conselhos hipotéticos com if I were you.",vocab:[{en:"If I were you",pt:"Se eu fosse você"},{en:"Advice",pt:"Conselho"},{en:"In your shoes",pt:"No seu lugar"},{en:"I would...",pt:"Eu faria..."},{en:"I wouldn't...",pt:"Eu não faria..."},{en:"Wise",pt:"Sábio"},{en:"Honest",pt:"Honesto"},{en:"Patient",pt:"Paciente"},{en:"Careful",pt:"Cuidadoso"},{en:"Confident",pt:"Confiante"}],grammar:{title:"Conselhos com If I Were You",rule:"IF I WERE YOU, I WOULD/N'T + verbo: If I were you, I would study more. Se estou dando conselho não preciso do 'if': I would try this if I were you. 'If I were in your shoes' = variante formal.",table:[{form:"Conselho positivo",example:"If I were you, I would accept the offer.",pt:"Se eu fosse você, aceitaria a oferta."},{form:"Conselho negativo",example:"If I were you, I wouldn't skip practice.",pt:"Se eu fosse você, não pularia a prática."},{form:"Variante",example:"If I were in your shoes, I'd start early.",pt:"Se estivesse no seu lugar, começaria cedo."}]},reading:{title:"A Piece of Advice",text:"My friend is confused about his career. I told him: 'If I were you, I wouldn't worry too much.' I also said: 'If I were in your shoes, I would keep learning English.' He asked: 'What would you do about the course?' I answered: 'If I were you, I would finish it, because it's almost done.' He smiled. Good advice builds good friends.",translation:"Meu amigo está confuso sobre a carreira dele. Eu disse a ele: 'Se eu fosse você, não me preocuparia tanto.' Também disse: 'Se eu estivesse no seu lugar, continuaria aprendendo inglês.' Ele perguntou: 'O que você faria sobre o curso?' Respondi: 'Se eu fosse você, terminaria, porque está quase pronto.' Ele sorriu. Bons conselhos constroem boas amizades."},quiz:[{q:"Conselho:",options:["If I were you, I would accept.","If I was you, I would.","If I am you, I do."],ans:"If I were you, I would accept."},{q:"Negativo:",options:["If I were you, I wouldn't skip.","If I were you, I don't skip.","If I were, not skip."],ans:"If I were you, I wouldn't skip."},{q:"Variante formal:",options:["If I were in your shoes, I'd start.","If I am in your shoes, I start.","Your shoes if I, start I."],ans:"If I were in your shoes, I'd start."}],chunks:[{en:"if I were you, I would accept",pt:"se eu fosse você, aceitaria"},{en:"if I were in your shoes, I'd start early",pt:"se estivesse no seu lugar, começaria cedo"},{en:"I wouldn't skip practice",pt:"eu não pularia a prática"}],listeningScript:"My advice: if I were you, I wouldn't worry too much. If I were in your shoes, I would keep learning English. And I would finish the course. It's almost done!",speakingPrompt:"Dê 3 conselhos a um amigo: 'If I were you, I would... If I were in your shoes, I'd...'",lightReading:"Mentors speak second conditional: 'If I were starting my career today, I would learn English first' — advice from experience uses the hypothetical voice.",journalPrompt:"Today is Day 148. I have given advice in English.",tip:"DICA DE TOM: 'If I were you, I would...' é um conselho EMOCIONAL (opinião pessoal). Para suavizar: 'If I were you, I'd consider...' (considerar) — menos impositivo, mais profissional."},149:{dayName:"Dia 149 — Quarta-feira",title:"Could e Might no Second Conditional",focus:"Adicionar possibilidade e capacidade aos hipotéticos.",vocab:[{en:"Could",pt:"Poderia"},{en:"Might",pt:"Talvez (pudesse)"},{en:"Possibility",pt:"Possibilidade"},{en:"Ability",pt:"Capacidade"},{en:"Maybe",pt:"Talvez"},{en:"Uncertain",pt:"Incerteza"},{en:"Chance",pt:"Chance"},{en:"Lucky",pt:"Sortudo"},{en:"Opportunity",pt:"Oportunidade"},{en:"Result",pt:"Resultado"}],grammar:{title:"Would / Could / Might",rule:"WOULD = certeza hipotética. COULD = capacidade ou possibilidade: If I spoke English, I could work abroad. MIGHT = possibilidade incerta: If I saved money, I might buy a house. Escala: would (mais certo) > could (capacidade) > might (menos certo).",table:[{form:"Capacidade",example:"If I spoke English, I could work abroad.",pt:"Se eu falasse inglês, poderia trabalhar no exterior."},{form:"Possibilidade",example:"If I saved money, I might buy a house.",pt:"Se eu poupasse dinheiro, talvez comprasse uma casa."},{form:"Certeza",example:"If she invited me, I would go.",pt:"Se ela me convidasse, eu iria."}]},reading:{title:"The English Dream",text:"If I spoke fluent English, I could work for international companies. I might travel more if I had the money. If I knew three languages, I would be very confident. My friend: 'If you practiced harder, you could reach fluency faster.' Maybe. But if I didn't enjoy learning, I wouldn't have started. Dreams with conditions are still dreams: they guide me.",translation:"Se eu falasse inglês fluente, poderia trabalhar para empresas internacionais. Talvez viajasse mais se tivesse o dinheiro. Se eu soubesse três idiomas, seria muito confiante. Meu amigo: 'Se você praticasse mais, poderia alcançar a fluência mais rápido.' Talvez. Mas se eu não gostasse de aprender, não teria começado. Sonhos com condições ainda são sonhos: eles me guiam."},quiz:[{q:"Capacidade:",options:["If I spoke English, I could work abroad.","If I spoke English, I work abroad.","If I will speak, I could work."],ans:"If I spoke English, I could work abroad."},{q:"Possibilidade incerta:",options:["If I saved money, I might buy a house.","If I saved money, I bought a house.","If I save money, I might buy."],ans:"If I saved money, I might buy a house."},{q:"Certeza hipotética:",options:["If she invited me, I would go.","If she invites me, I would go.","If she invited me, I will go."],ans:"If she invited me, I would go."}],chunks:[{en:"if I spoke English, I could work abroad",pt:"se eu falasse inglês, poderia trabalhar fora"},{en:"if I saved money, I might buy a house",pt:"se eu poupasse, talvez comprasse uma casa"},{en:"if she invited me, I would go",pt:"se ela me convidasse, eu iria"}],listeningScript:"Dream analysis! If I spoke English, I could work abroad. I might travel if I had money. My friend says: if I practiced harder, I could reach fluency. Dreams guide me!",speakingPrompt:"Fale com a escala: 'If I... I would... I could... I might...'",lightReading:"Career advisors use the full scale: 'If you learned X, you could apply', 'you might earn more', 'you would stand out' — hypothetical job advice.",journalPrompt:"Today is Day 149. I have learned would, could and might.",tip:"DICA DE ESCALA: memorize a ordem de certeza: WOULD (quase certo) → COULD (capacidade) → MIGHT (talvez). Escolha pela quantidade de risco na sua frase."},150:{dayName:"Dia 150 — Quinta-feira",title:"Cenários Tech Hipotéticos",focus:"Usar o second conditional em discussões de tecnologia.",vocab:[{en:"Scenario",pt:"Cenário"},{en:"Hypothetical",pt:"Hipotético"},{en:"What if...?",pt:"E se...?"},{en:"Rewrite",pt:"Reescrever"},{en:"Rewrite the system",pt:"Reescrever o sistema"},{en:"Start from scratch",pt:"Começar do zero"},{en:"Choose",pt:"Escolher"},{en:"Prefer",pt:"Preferir"},{en:"Switch",pt:"Trocar"},{en:"Extend",pt:"Estender"}],grammar:{title:"What If...? em Tecnologia",rule:"Discussões técnicas hipotéticas: What would you do if the system failed? If we rewrote the system, it would be faster. Em conversas de entrevista: If I were the lead, I would refactor first.",table:[{form:"Cenário",example:"If we rewrote the system, it would be faster.",pt:"Se reescrevêssemos o sistema, seria mais rápido."},{form:"Pergunta",example:"What would you do if the client left?",pt:"O que você faria se o cliente fosse embora?"},{form:"Preferência",example:"If I had to choose, I would pick Vue.",pt:"Se eu tivesse que escolher, escolheria Vue."}]},reading:{title:"The Tech Debate",text:"In the meeting, we debated the future of our stack. I asked: 'What would happen if we rewrote everything?' My colleague said: 'If we started from scratch, we would save a lot of debt.' Another said: 'If we kept the old code, we wouldn't risk anything.' If I were the tech lead, I would test both options first. In the end, we agreed: if we had more time, we would both try. Good debate!",translation:"Na reunião, debatemos o futuro do nosso stack. Perguntei: 'O que aconteceria se reescrevêssemos tudo?' Meu colega disse: 'Se começássemos do zero, economizaríamos muita dívida.' Outro disse: 'Se mantivéssemos o código antigo, não arriscaríamos nada.' Se eu fosse o líder técnico, testaria as duas opções antes. No fim, concordamos: se tivéssemos mais tempo, tentaríamos as duas. Bom debate!"},quiz:[{q:"Cenário:",options:["If we rewrote the system, it would be faster.","If we rewrite the system, it will be faster.","If we rewrote, it is faster."],ans:"If we rewrote the system, it would be faster."},{q:"Pergunta hipotética:",options:["What would you do if the client left?","What will you do if client left?","What you do if the client?"],ans:"What would you do if the client left?"},{q:"Complete: 'If I ___ to choose, I would pick Vue.'",options:["had","have","will have"],ans:"had"}],chunks:[{en:"if we rewrote the system, it would be faster",pt:"se reescrevêssemos o sistema, seria mais rápido"},{en:"if I were the tech lead, I would test both",pt:"se eu fosse o líder técnico, testaria as duas"},{en:"what would you do if the client left?",pt:"o que você faria se o cliente fosse embora?"}],listeningScript:"Tech debate! If we rewrote everything, we would save debt. If we kept the old code, we wouldn't risk anything. If I were the lead, I would test both. Great debate!",speakingPrompt:"Debata um tema tech: 'If we..., we would... What would you do if...? If I were..., I would...'",lightReading:"System design interviews are second conditional exams: 'If you had to scale this to a million users, what would you change?' — hypothetical architecture language.",journalPrompt:"Today is Day 150. I have debated technology in English.",tip:"DICA DE ENTREVISTA DE SISTEMAS: frases como 'If I were the lead, I would...' mostram liderança. Sempre feche com uma decisão: 'I would choose X because...'"},151:{dayName:"Dia 151 — Sexta-feira",title:"Zero Conditional (Fatos e Verdades)",focus:"Expressar fatos e leis com o zero conditional.",vocab:[{en:"Fact",pt:"Fato"},{en:"Truth",pt:"Verdade"},{en:"Law",pt:"Lei"},{en:"Universal",pt:"Universal"},{en:"Always",pt:"Sempre"},{en:"Whenever",pt:"Sempre que"},{en:"Rule of thumb",pt:"Regra prática"},{en:"Boil",pt:"Ferver"},{en:"Freeze",pt:"Congelar"},{en:"Happen",pt:"Acontecer"}],grammar:{title:"Zero Conditional",rule:"IF/WHEN + presente, presente: If you heat water, it boils. Verdades universais e hábitos. É o único condicional SEM will/would: If it rains, the game stops. USO TECH: If the code compiles, it works (nem sempre!).",table:[{form:"Fato",example:"If you heat water, it boils.",pt:"Se você aquecer água, ela ferve."},{form:"Hábito",example:"When I study early, I learn more.",pt:"Quando estudo cedo, aprendo mais."},{form:"Regra do sistema",example:"If validation fails, the form doesn't send.",pt:"Se a validação falhar, o formulário não envia."}]},reading:{title:"Tech Truths",text:"There are universal tech truths. If you don't test, bugs appear. If you document well, teams thank you. If the server is overloaded, pages get slow. When I debug, I read the logs first. If I skip review, I make mistakes. These truths are simple: if you take care of the basics, everything works better. Zero conditional = common sense in grammar form.",translation:"Existem verdades universais de tecnologia. Se você não testar, bugs aparecem. Se você documentar bem, as equipes agradecem. Se o servidor estiver sobrecarregado, as páginas ficam lentas. Quando depuro, leio os logs primeiro. Se eu pular a revisão, cometo erros. Essas verdades são simples: se você cuidar do básico, tudo funciona melhor. Zero conditional = senso comum em forma de gramática."},quiz:[{q:"Fato universal:",options:["If you heat water, it boils.","If you heat water, it will boil.","If you heated water, it boils."],ans:"If you heat water, it boils."},{q:"Hábito:",options:["When I study early, I learn more.","When I study early, I learned more.","When I studied early, I will learn."],ans:"When I study early, I learn more."},{q:"Complete: 'If you don't test, bugs ___'",options:["appear","will appear","would appear"],ans:"appear"}],chunks:[{en:"if you don't test, bugs appear",pt:"se você não testar, bugs aparecem"},{en:"when I debug, I read the logs first",pt:"quando depuro, leio os logs primeiro"},{en:"if you take care of the basics, everything works",pt:"se você cuidar do básico, tudo funciona"}],listeningScript:"Tech truths! If you don't test, bugs appear. If you document well, teams thank you. When I debug, I read logs first. If you care about basics, everything works!",speakingPrompt:"Fale 5 verdades: 'If/When I..., ...' sobre estudo, trabalho e vida.",lightReading:"Best practices are zero conditional: 'If you run the formatter before committing, the code stays clean' — team guidelines written as universal truths.",journalPrompt:"Today is Day 151. I have learned the Zero Conditional.",tip:"DICA DE GAMBIARRA: se você quer soar experiente, use zero conditional para 'best practices': If you comment your code, others understand it. Fato, não opinião."},152:{dayName:"Dia 152 — Sábado",title:"Consolidação da Semana 22 + TESTE DE SÁBADO 22",focus:"Testar second conditional, if I were you, could/might e zero conditional.",vocab:[{en:"Hypothesis",pt:"Hipótese"},{en:"Imagination",pt:"Imaginação"},{en:"Decision",pt:"Decisão"},{en:"Risk",pt:"Risco"},{en:"Choice",pt:"Escolha"},{en:"Dream",pt:"Sonho"},{en:"Advice",pt:"Conselho"},{en:"Truth",pt:"Verdade"},{en:"Possibility",pt:"Possibilidade"},{en:"Future",pt:"Futuro"}],grammar:{title:"Resumo da Semana 22",rule:"Second Conditional: IF + passado, WOULD + verbo (imaginário). COULD = capacidade, MIGHT = possibilidade. If I were you = conselho. Zero Conditional: IF + presente, presente (fatos). Compare: real (first) vs imaginário (second) vs fático (zero).",table:[{form:"Imaginário",example:"If I had money, I would travel.",pt:"Se eu tivesse dinheiro, viajaria."},{form:"Conselho",example:"If I were you, I'd accept.",pt:"Se eu fosse você, aceitaria."},{form:"Fato",example:"If you practice, you improve.",pt:"Se você pratica, melhora."}]},reading:{title:"The Dream Decision",text:"I have been thinking about my future. If I had a mentor, I would learn much faster. If I were braver, I would apply for international jobs. If I changed cities, I might find more opportunities. But let's be honest: if you don't take risks, you don't grow. My decision? If the opportunity came, I would take it. Dreams are the first step: if you dream, you plan; if you plan, you act.",translation:"Tenho pensado no meu futuro. Se eu tivesse um mentor, aprenderia muito mais rápido. Se eu fosse mais corajoso, me candidataria a empregos internacionais. Se eu mudasse de cidade, talvez encontrasse mais oportunidades. Mas sejamos honestos: se você não assume riscos, não cresce. Minha decisão? Se a oportunidade chegasse, eu a pegaria. Sonhos são o primeiro passo: se você sonha, planeja; se planeja, age."},quiz:[{q:"Complete: 'If I had a mentor, I ___ learn faster.'",options:["would","will","did"],ans:"would"},{q:"Complete: 'If I changed cities, I ___ find opportunities.'",options:["might","will","do"],ans:"might"},{q:"Complete: 'If you don't take risks, you ___ grow.'",options:["don't","won't","wouldn't"],ans:"don't"}],chunks:[{en:"if I had a mentor, I would learn faster",pt:"se eu tivesse um mentor, aprenderia mais rápido"},{en:"if you dream, you plan; if you plan, you act",pt:"se você sonha, planeja; se planeja, age"},{en:"if the opportunity came, I would take it",pt:"se a oportunidade chegasse, eu a pegaria"}],listeningScript:"The dream decision! If I had a mentor, I would learn faster. If I were braver, I would apply abroad. If you don't take risks, you don't grow. If you dream, you plan!",speakingPrompt:"Grave seu Teste de Sábado: 'If I had... I would... If I were... I would... If you..., ...'",lightReading:"Vision statements are conditional dreams: 'If we had the right team, we would change the industry' — founders think in second conditional.",journalPrompt:"Today is Day 152. I have passed my Saturday Test 22!",tip:"DICA DE LIGAÇÃO: você já tem os 3 básicos: ZERO (fato), FIRST (real), SECOND (imaginário). Escolha o condicional pela REALIDADE da situação."},153:{dayName:"Dia 153 — Domingo",title:"Revisão da Semana 22 & Imersão Leve",focus:"Revisar condicionais hipotéticos com leitura leve.",vocab:[{en:"Compare",pt:"Comparar"},{en:"Contrast",pt:"Contraste"},{en:"Opinion",pt:"Opinião"},{en:"Story",pt:"História"},{en:"Movie",pt:"Filme"},{en:"Character",pt:"Personagem"},{en:"Plot",pt:"Enredo"},{en:"Ending",pt:"Final"},{en:"Choose",pt:"Escolher"},{en:"Imagine",pt:"Imaginar"}],grammar:{title:"Checkpoint 153 — Condicionais na Fala Real",rule:"Filmes e livros usam o second conditional o tempo todo: If I were her, I would... Quando algo é hipotético OU um conselho → second. Quando é realidade possível → first.",table:[{form:"Filme",example:"If I were the main character, I would trust my team.",pt:"Se eu fosse o protagonista, confiaria na minha equipe."},{form:"Realidade",example:"If I watch two episodes, I will sleep later.",pt:"Se eu assistir a dois episódios, dormirei mais tarde."},{form:"Comparação",example:"This movie wouldn't be good if it had no action.",pt:"Este filme não seria bom se não tivesse ação."}]},reading:{title:"The Movie Debate",text:"Last night, I watched a tech movie with friends. I said: 'If I were the main character, I would shut down the system immediately.' My friend disagreed: 'If you did that, you would lose everything.' Another said: 'The ending wouldn't be good if they deleted the data.' We laughed. Movies are great second conditional gyms: if you watch them in English, you learn without studying.",translation:"Ontem à noite, assisti a um filme tech com amigos. Eu disse: 'Se eu fosse o protagonista, desligaria o sistema imediatamente.' Meu amigo discordou: 'Se você fizesse isso, perderia tudo.' Outro disse: 'O final não seria bom se eles apagassem os dados.' Rimos. Filmes são ótimas academias de second conditional: se você os assiste em inglês, aprende sem estudar."},quiz:[{q:"Hipotético sobre filme:",options:["If I were the character, I would shut down.","If I am the character, I will shut down.","If I was the character, I shut down."],ans:"If I were the character, I would shut down."},{q:"Hipótese com consequência:",options:["If you did that, you would lose everything.","If you do that, you lost everything.","If you did that, you lose."],ans:"If you did that, you would lose everything."},{q:"Complete: 'The ending wouldn't be good if they ___ the data.'",options:["deleted","delete","will delete"],ans:"deleted"}],chunks:[{en:"if I were the main character, I would shut down",pt:"se eu fosse o protagonista, desligaria"},{en:"if you did that, you would lose everything",pt:"se você fizesse isso, perderia tudo"},{en:"if you watch movies in English, you learn",pt:"se você assiste filmes em inglês, aprende"}],listeningScript:"Movie debate! If I were the character, I would shut down. If you did that, you would lose everything. And the ending wouldn't be good if they deleted the data. Ha!",speakingPrompt:"Debata um filme/série: 'If I were..., I would... If they..., it would...'",lightReading:"Every movie review is full of conditionals: 'It would be better if the ending were shorter', 'If you like AI, you will love this' — criticism is hypothetical by nature.",journalPrompt:"Today is Day 153. I have reviewed conditionals with fun.",tip:"DICA DE CINEMA: ative legendas em inglês em filmes tech. Você vai caçar 'would have', 'if I were' naturalmente — a fala de filme é o segundo conditional em estado puro."},154:{dayName:"Dia 154 — Segunda-feira",title:"Passive Voice no Presente (Is Made, Are Built)",focus:"Usar a voz passiva para descrever processos.",vocab:[{en:"Passive voice",pt:"Voz passiva"},{en:"Be + participle",pt:"Ser + particípio"},{en:"Made",pt:"Feito"},{en:"Built",pt:"Construído"},{en:"Designed",pt:"Projetado"},{en:"Developed",pt:"Desenvolvido"},{en:"Stored",pt:"Armazenado"},{en:"Processed",pt:"Processado"},{en:"Created",pt:"Criado"},{en:"Used",pt:"Usado"}],grammar:{title:"Voz Passiva (Presente)",rule:"SUJEITO + IS/ARE + PARTICÍPIO: The code is written by the team. Usamos quando o OBJETO importa mais que quem faz: data is processed, files are stored. Em tech escrevemos muito assim: The data is stored in the cloud.",table:[{form:"Processo",example:"The code is reviewed before deployment.",pt:"O código é revisado antes do deploy."},{form:"Fato técnico",example:"Data is stored in the cloud.",pt:"Os dados são armazenados na nuvem."},{form:"Com agente (by)",example:"The app is built by our team.",pt:"O app é construído pela nossa equipe."}]},reading:{title:"How Software Is Made",text:"Have you ever wondered how software is made? First, the requirements are collected. Then, the design is created. After that, the code is written by developers. Later, the app is tested by the QA team. Finally, the product is delivered to the users. Every step is checked carefully. When good processes are followed, great apps are born.",translation:"Você já se perguntou como o software é feito? Primeiro, os requisitos são coletados. Depois, o design é criado. Depois disso, o código é escrito por desenvolvedores. Em seguida, o app é testado pela equipe de QA. Finalmente, o produto é entregue aos usuários. Cada etapa é verificada com cuidado. Quando bons processos são seguidos, ótimos apps nascem."},quiz:[{q:"Passiva correta:",options:["The code is reviewed before deployment.","The code reviews before deployment.","The code is review."],ans:"The code is reviewed before deployment."},{q:"Complete: 'Data ___ stored in the cloud.'",options:["is","are","am"],ans:"is"},{q:"Complete: 'The app is built ___ our team.'",options:["by","for","with"],ans:"by"}],chunks:[{en:"the code is reviewed before deployment",pt:"o código é revisado antes do deploy"},{en:"data is stored in the cloud",pt:"os dados são armazenados na nuvem"},{en:"the app is built by our team",pt:"o app é construído pela nossa equipe"}],listeningScript:"How is software made? Requirements are collected. The design is created. The code is written. The app is tested. Finally, it is delivered. Good processes make great apps!",speakingPrompt:"Descreva um processo na passiva: 'First, X is... Then, Y is... Finally, Z is...'",lightReading:"Technical documentation prefers passive: 'The package is installed via npm', 'The database is configured in config.js' — passive = focus on the action, not the actor.",journalPrompt:"Today is Day 154. I have learned the passive voice.",tip:"DICA DE DOCS: na leitura de documentação, 70% dos verbos estão na passiva. Se você entender passiva, documentação técnica vira leitura leve. Vale o investimento!"},155:{dayName:"Dia 155 — Terça-feira",title:"Passive no Passado (Was Built, Were Fixed)",focus:"Relatar fatos passados na voz passiva.",vocab:[{en:"Was built",pt:"Foi construído"},{en:"Were fixed",pt:"Foram corrigidos"},{en:"Was created",pt:"Foi criado"},{en:"Was launched",pt:"Foi lançado"},{en:"Was discovered",pt:"Foi descoberto"},{en:"Were reported",pt:"Foram reportados"},{en:"Was released",pt:"Foi lançado (release)"},{en:"Was found",pt:"Foi encontrado"},{en:"Was solved",pt:"Foi resolvido"},{en:"Was introduced",pt:"Foi introduzido"}],grammar:{title:"Passiva no Passado",rule:"SUJEITO + WAS/WERE + PARTICÍPIO: The bug was fixed yesterday. Singular usa WAS (The bug was), plural usa WERE (The bugs were). Em relatórios de incidente: The issue was reported at 9 AM and was solved at 11.",table:[{form:"Singular",example:"The bug was fixed yesterday.",pt:"O bug foi corrigido ontem."},{form:"Plural",example:"The bugs were fixed by the team.",pt:"Os bugs foram corrigidos pela equipe."},{form:"Incidente",example:"The issue was reported at 9 AM.",pt:"O problema foi reportado às 9 da manhã."}]},reading:{title:"The Incident Report",text:"Yesterday was a hard day. At 9 AM, a serious bug was reported. The problem was found in the payment module. Three servers were affected. The fix was created quickly and was deployed at 11. Fortunately, no data was lost. After the incident, a full review was done. Lessons were documented. Experience was gained. Every crisis is an opportunity in disguise.",translation:"Ontem foi um dia difícil. Às 9h, um bug sério foi reportado. O problema foi encontrado no módulo de pagamento. Três servidores foram afetados. A correção foi criada rapidamente e foi implantada às 11h. Felizmente, nenhum dado foi perdido. Após o incidente, uma revisão completa foi feita. As lições foram documentadas. Experiência foi ganha. Toda crise é uma oportunidade disfarçada."},quiz:[{q:"Singular:",options:["The bug was fixed yesterday.","The bug were fixed yesterday.","The bug was fix."],ans:"The bug was fixed yesterday."},{q:"Plural:",options:["The bugs were fixed by the team.","The bugs was fixed by the team.","The bugs were fix by team."],ans:"The bugs were fixed by the team."},{q:"Complete: 'No data ___ lost.'",options:["was","were","is"],ans:"was"}],chunks:[{en:"the bug was fixed yesterday",pt:"o bug foi corrigido ontem"},{en:"three servers were affected",pt:"três servidores foram afetados"},{en:"lessons were documented",pt:"as lições foram documentadas"}],listeningScript:"Incident report! At 9 AM, a serious bug was reported. The problem was found in payments. The fix was deployed at 11. No data was lost. Lessons were documented. Crisis = opportunity!",speakingPrompt:"Relate um incidente: 'At..., X was reported. It was found... The fix was... No data was...'",lightReading:"Incident reports are passive masterpieces: 'The outage was caused by...', 'The rollback was executed...' — objectivity lives in the passive voice.",journalPrompt:"Today is Day 155. I have reported events in passive.",tip:"DICA DE RELATÓRIO: em incidentes, use passiva para relatar FATO (the bug was fixed) e ativa para responsabilidade (I fixed it). Equilíbrio = profissionalismo."},156:{dayName:"Dia 156 — Quarta-feira",title:"Passiva com Modais (Can Be, Must Be, Should Be)",focus:"Combinar passiva com can, must e should.",vocab:[{en:"Can be done",pt:"Pode ser feito"},{en:"Must be tested",pt:"Deve ser testado"},{en:"Should be fixed",pt:"Deveria ser corrigido"},{en:"May be delayed",pt:"Pode ser adiado"},{en:"Could be improved",pt:"Poderia ser melhorado"},{en:"Has to be",pt:"Tem que ser"},{en:"Requirement",pt:"Requisito"},{en:"Security",pt:"Segurança"},{en:"Access",pt:"Acesso"},{en:"Approval",pt:"Aprovação"}],grammar:{title:"Modal + Passiva",rule:"MODAL + BE + PARTICÍPIO: can be done, must be tested, should be fixed. A ação é obrigatória (must), recomendada (should) ou possível (can). Exemplos de requisitos: The password must be changed every 90 days.",table:[{form:"Possibilidade",example:"This task can be done today.",pt:"Esta tarefa pode ser feita hoje."},{form:"Obrigação",example:"The tests must be run before release.",pt:"Os testes devem ser executados antes do release."},{form:"Recomendação",example:"The documentation should be updated.",pt:"A documentação deveria ser atualizada."}]},reading:{title:"Security Rules",text:"Every company has security rules. Passwords must be changed every 90 days. New code must be reviewed before deployment. Access can be granted only with approval. Sensitive data must not be shared. Security tests should be run monthly. If rules are followed, risks can be avoided. Simple rules, strong systems.",translation:"Toda empresa tem regras de segurança. Senhas devem ser trocadas a cada 90 dias. Código novo deve ser revisado antes do deploy. O acesso só pode ser concedido com aprovação. Dados sensíveis não devem ser compartilhados. Testes de segurança deveriam ser executados mensalmente. Se as regras são seguidas, riscos podem ser evitados. Regras simples, sistemas fortes."},quiz:[{q:"Possibilidade:",options:["This task can be done today.","This task can done today.","This task can be do."],ans:"This task can be done today."},{q:"Obrigação:",options:["The tests must be run before release.","The tests must be run before releases.","The tests must run be before."],ans:"The tests must be run before release."},{q:"Complete: 'Risk ___ be avoided.'",options:["can","can't","does"],ans:"can"}],chunks:[{en:"this task can be done today",pt:"esta tarefa pode ser feita hoje"},{en:"the tests must be run before release",pt:"os testes devem ser executados antes do release"},{en:"access can be granted with approval",pt:"o acesso só pode ser concedido com aprovação"}],listeningScript:"Security rules! Passwords must be changed every 90 days. Code must be reviewed. Access can be granted with approval. Data must not be shared. Risks can be avoided!",speakingPrompt:"Crie regras com modais na passiva: 'X must be... Y can be... Z should be...'",lightReading:"Security policies are modal-passive documents: 'Data must be encrypted', 'Access should be reviewed quarterly' — policies don't say who, they say what.",journalPrompt:"Today is Day 156. I have learned modal passives.",tip:"DICA DE POLÍTICA: em regras formais, passiva + modal = tom impessoal profissional: 'The report must be submitted on Friday.' Sem 'você' — só a regra."},157:{dayName:"Dia 157 — Quinta-feira",title:"Passiva na Escrita Técnica",focus:"Aplicar a passiva em documentações e textos técnicos.",vocab:[{en:"Documentation",pt:"Documentação"},{en:"Instructions",pt:"Instruções"},{en:"Reference",pt:"Referência"},{en:"Guide",pt:"Guia"},{en:"Example",pt:"Exemplo"},{en:"Installed",pt:"Instalado"},{en:"Configured",pt:"Configurado"},{en:"Enabled",pt:"Ativado"},{en:"Disabled",pt:"Desativado"},{en:"Defined",pt:"Definido"}],grammar:{title:"Passiva em Manuais",rule:"Manuais instrutivos usam passiva para focar na AÇÃO: The package is installed with npm. O serviço é ativado no boot: The service is enabled on boot. A passiva mantém o texto objetivo: quem faz é o leitor, implícito.",table:[{form:"Instalação",example:"The package is installed with npm.",pt:"O pacote é instalado com npm."},{form:"Configuração",example:"The database is configured in config.js.",pt:"O banco é configurado no config.js."},{form:"Ativação",example:"The service is enabled on boot.",pt:"O serviço é ativado na inicialização."}]},reading:{title:"A Little Manual",text:"This app was designed with simplicity in mind. First, the app is downloaded from the store. Then, the account is created with your email. The preferences are configured in Settings. Notifications can be enabled or disabled. The data is stored locally for privacy. All features are documented in the guide. When something is unclear, the FAQ is a great friend.",translation:"Este app foi projetado com simplicidade em mente. Primeiro, o app é baixado da loja. Depois, a conta é criada com seu e-mail. As preferências são configuradas em Configurações. As notificações podem ser ativadas ou desativadas. Os dados são armazenados localmente por privacidade. Todas as funcionalidades são documentadas no guia. Quando algo não está claro, o FAQ é um grande amigo."},quiz:[{q:"Manual:",options:["The package is installed with npm.","The developer installs the package with npm.","Install the package by developer."],ans:"The package is installed with npm."},{q:"Complete: 'The database is ___ in config.js.'",options:["configured","configures","configuring"],ans:"configured"},{q:"Complete: 'Notifications can be ___ or disabled.'",options:["enabled","enable","enables"],ans:"enabled"}],chunks:[{en:"the package is installed with npm",pt:"o pacote é instalado com npm"},{en:"the database is configured in config.js",pt:"o banco é configurado no config.js"},{en:"the data is stored locally",pt:"os dados são armazenados localmente"}],listeningScript:"Quick manual! The app is downloaded from the store. The account is created with email. Preferences are configured in Settings. Notifications can be enabled or disabled. Easy!",speakingPrompt:"Explique um produto na passiva: 'The app is... It can be... The data is...'",lightReading:"README files are passive sections: 'The project is structured as follows', 'Tests are run with...' — READMEs are the most read passive texts in the world.",journalPrompt:"Today is Day 157. I have written like a manual.",tip:"DICA DE README: ao escrever documentação própria (mesmo que simples), use passiva: 'The API is called with...', 'Errors are returned as JSON'. É como documentações profissionais soam."},158:{dayName:"Dia 158 — Sexta-feira",title:"Ativa vs Passiva (Quando Usar Cada Uma)",focus:"Escolher entre voz ativa e passiva com consciência.",vocab:[{en:"Active voice",pt:"Voz ativa"},{en:"Responsibility",pt:"Responsabilidade"},{en:"Clarity",pt:"Clareza"},{en:"Focus",pt:"Foco"},{en:"Emphasis",pt:"Ênfase"},{en:"Unknown",pt:"Desconhecido"},{en:"Obvious",pt:"Óbvio"},{en:"Mystery",pt:"Mistério"},{en:"Direct",pt:"Direto"},{en:"Choose",pt:"Escolher"}],grammar:{title:"Ativa vs Passiva",rule:"ATIVA = quem faz importa: I fixed the bug. PASSIVA = a ação importa ou o autor é desconhecido: The bug was fixed. Regra de bolso: 'by + pessoa' deixa a passiva fraca → prefira ativa. Passiva sem 'by' → ok e comum em tech.",table:[{form:"Ativa (responsabilidade)",example:"I fixed the bug at midnight.",pt:"Corrigi o bug à meia-noite."},{form:"Passiva (ação)",example:"The bug was fixed quickly.",pt:"O bug foi corrigido rapidamente."},{form:"Autor desconhecido",example:"The settings have been changed.",pt:"As configurações foram alteradas."}]},reading:{title:"The Two Voices",text:"When should I use each voice? If I want to show responsibility, I use the active: 'I designed the new system.' If the result matters more, I use the passive: 'The new system was designed in one month.' If the author is unknown: 'The files were deleted.' English professionals switch voices constantly. Understanding the switch makes you sound natural.",translation:"Quando devo usar cada voz? Se quero mostrar responsabilidade, uso a ativa: 'Eu projetei o novo sistema.' Se o resultado importa mais, uso a passiva: 'O novo sistema foi projetado em um mês.' Se o autor é desconhecido: 'Os arquivos foram deletados.' Profissionais de inglês trocam de voz constantemente. Entender a troca faz você soar natural."},quiz:[{q:"Responsabilidade:",options:["I designed the new system.","The new system was designed.","The system designed me."],ans:"I designed the new system."},{q:"Resultado em foco:",options:["The new system was designed in one month.","I designed the new system in one month and it was me.","I the system designed."],ans:"The new system was designed in one month."},{q:"Autor desconhecido:",options:["The files were deleted.","Someone deleted the files, someone.","The files was deleted."],ans:"The files were deleted."}],chunks:[{en:"I designed the new system",pt:"eu projetei o novo sistema"},{en:"the system was designed in one month",pt:"o sistema foi projetado em um mês"},{en:"the files were deleted",pt:"os arquivos foram deletados"}],listeningScript:"The two voices! Responsibility? Active: I designed the system. Result? Passive: It was designed in a month. Unknown author? Passive: The files were deleted. Switch voices naturally!",speakingPrompt:"Conte um fato das duas formas: 'I did...' (ativa) e 'It was done...' (passiva).",lightReading:"Newspapers and incident reports use passive for politeness and facts: 'Mistakes were made' — the passive softens responsibility; the active claims it.",journalPrompt:"Today is Day 158. I have learned to choose my voice.",tip:"DICA FINAL: curta e direta: responsabilidade e histórias → ATIVA. Processos, relatórios, documentação → PASSIVA. Quando usar 'by' deixar a frase longa, reescreva na ativa."},159:{dayName:"Dia 159 — Sábado",title:"Consolidação da Semana 23 + TESTE DE SÁBADO 23",focus:"Testar a voz passiva completa: presente, passado e modais.",vocab:[{en:"Voice",pt:"Voz"},{en:"Process",pt:"Processo"},{en:"Report",pt:"Relatório"},{en:"Incident",pt:"Incidente"},{en:"Rule",pt:"Regra"},{en:"Review",pt:"Revisão"},{en:"Document",pt:"Documento"},{en:"Result",pt:"Resultado"},{en:"Action",pt:"Ação"},{en:"Progress",pt:"Progresso"}],grammar:{title:"Resumo da Semana 23",rule:"Passiva presente: is/are + particípio (is built). Passiva passada: was/were + particípio (was fixed). Passiva com modal: can/must/should + be + particípio (can be done). Ativa = quem faz; passiva = a ação.",table:[{form:"Presente",example:"The app is tested weekly.",pt:"O app é testado semanalmente."},{form:"Passado",example:"The bug was fixed yesterday.",pt:"O bug foi corrigido ontem."},{form:"Modal",example:"Passwords must be changed regularly.",pt:"As senhas devem ser trocadas regularmente."}]},reading:{title:"The Passive Week",text:"This week, the passive voice was studied deeply. Sentences were built in three forms: present, past and modal. The exercises were completed without major errors. My confidence was increased. Yesterday, a mini manual was written by me. The rules were reviewed one more time. Progress was made, and the next goal is clear: professional interviews. Great effort is never wasted.",translation:"Esta semana, a voz passiva foi estudada a fundo. Frases foram construídas em três formas: presente, passado e modal. Os exercícios foram completados sem erros graves. Minha confiança foi aumentada. Ontem, um mini manual foi escrito por mim. As regras foram revisadas mais uma vez. Progresso foi feito, e a próxima meta é clara: entrevistas profissionais. Grande esforço nunca é desperdiçado."},quiz:[{q:"Presente:",options:["The app is tested weekly.","The app is test weekly.","The app was tested weekly."],ans:"The app is tested weekly."},{q:"Passado:",options:["The bug was fixed yesterday.","The bug is fixed yesterday.","The bug was fix yesterday."],ans:"The bug was fixed yesterday."},{q:"Modal:",options:["Passwords must be changed regularly.","Passwords must changed regularly.","Passwords must be change regularly."],ans:"Passwords must be changed regularly."}],chunks:[{en:"the app is tested weekly",pt:"o app é testado semanalmente"},{en:"the bug was fixed yesterday",pt:"o bug foi corrigido ontem"},{en:"passwords must be changed regularly",pt:"as senhas devem ser trocadas regularmente"}],listeningScript:"The passive week! Three forms were studied: present, past, and modal. Exercises were completed. Confidence was increased. A manual was written. Progress was made. Never wasted!",speakingPrompt:"Grave seu Teste de Sábado: 'This week, X was studied. The exercises were... Progress was...' — tudo na passiva!",lightReading:"Project reviews love the passive: 'Code was reviewed, tests were run, bugs were fixed' — think of weekly summaries as passive documents.",journalPrompt:"Today is Day 159. I have passed my Saturday Test 23!",tip:"DICA DE RESUMO: resuma sua semana inteira na passiva (5 frases). É o exercício que fixa a voz passiva para sempre nos seus resumos profissionais."},160:{dayName:"Dia 160 — Domingo",title:"Revisão da Semana 23 & Imersão Leve",focus:"Revisar a passiva e preparar a reta final.",vocab:[{en:"Final stretch",pt:"Reta final"},{en:"Review",pt:"Revisão"},{en:"Interview",pt:"Entrevista"},{en:"Project",pt:"Projeto"},{en:"Portfolio",pt:"Portfólio"},{en:"Preparation",pt:"Preparação"},{en:"Confidence",pt:"Confiança"},{en:"Goal",pt:"Meta"},{en:"Milestone",pt:"Marco"},{en:"Ready",pt:"Pronto"}],grammar:{title:"Checkpoint 160 — Reta Final",rule:"Você completou a gramática essencial do B1: perfects, condicionais (zero/1/2) e voz passiva. Faltam 20 dias: entrevistas profissionais, revisão total e o teste final no Dia 180.",table:[{form:"O caminho",example:"The road was long, but progress was constant.",pt:"A estrada foi longa, mas o progresso foi constante."},{form:"A meta",example:"The final test will be taken on Day 180.",pt:"O teste final será feito no Dia 180."},{form:"A preparação",example:"Interviews will be practiced next week.",pt:"Entrevistas serão praticadas na próxima semana."}]},reading:{title:"Twenty Days to Go",text:"Only twenty days remain. The journey has been incredible: 160 days, every single one used. The basics were learned, the perfects were mastered, the conditionals were practiced, and the passive was understood. Now, interviews are next. When the final test is taken, I will be ready. Every effort was worth it. The finish line is close, and it is beautiful.",translation:"Faltam só vinte dias. A jornada foi incrível: 160 dias, todos aproveitados. O básico foi aprendido, os perfects foram dominados, os condicionais foram praticados e a passiva foi entendida. Agora, entrevistas são o próximo passo. Quando o teste final for feito, estarei pronto. Cada esforço valeu a pena. A linha de chegada está perto, e é linda."},quiz:[{q:"Complete: 'The basics ___ learned.'",options:["were","was","is"],ans:"were"},{q:"Complete: 'The final test will ___ taken on Day 180.'",options:["be","been","being"],ans:"be"},{q:"Complete: 'Interviews will be ___ next week.'",options:["practiced","practice","practicing"],ans:"practiced"}],chunks:[{en:"the journey has been incredible",pt:"a jornada foi incrível"},{en:"interviews will be practiced next week",pt:"entrevistas serão praticadas na próxima semana"},{en:"the finish line is close",pt:"a linha de chegada está perto"}],listeningScript:"Twenty days to go! The basics were learned, the perfects mastered, the conditionals practiced, the passive understood. Next: interviews. The finish line is close and beautiful!",speakingPrompt:"Fale da reta final: 'The road was long. The tests will be taken soon. Interviews will be practiced. I am ready.'",lightReading:"Conferences end with passive summaries: 'Lessons were learned, networks were built, ideas were shared' — the passive is the voice of reflection.",journalPrompt:"Today is Day 160. I have prepared for the final stretch.",tip:"DICA DE DESCANSO: daqui até o dia 180, o descanso também é treino. Durma bem: consolidação de memória acontece no sono. Sua mente está trabalhando por você."}},a=[{id:20,title:"Semana 20 — Storytelling B1 & Conquistas",daysRange:"Dias 133 a 139",subtitle:"Histórias, Números e Checkpoint B1",badgeClass:"badge-emerald",grammar:["Estrutura de histórias: perfect (contexto) → past (ação) → lição","Conquistas com números (reduced by 20%)","Revisão total dos perfects","Checkpoint B1 de leitura","Falar de projetos por 3-5 minutos"],vocab:"Lição de vida, conquistas quantificadas e portfólio",reading:"Histórias reais, blogs de dev e relatos de trabalho",listening:"Histórias de carreira e apresentações de projetos",speaking:"Maratonas de speaking: projetos, conquistas e lições",techBridge:"Currículo e portfólio com números e resultados",saturday:{recall:[["I have faced many challenges","enfrentei muitos desafios"],["last year, the project failed","ano passado, o projeto falhou"],["I have learned a huge lesson","aprendi uma lição enorme"],["I have reduced costs by 20%","reduzi custos em 20%"],["I have launched three products","lancei três produtos"],["I have led a team of five","liderei uma equipe de cinco"],["I have completed the course","completei o curso"],["I have been improving my speed","venho melhorando minha velocidade"],["I have been surprised by my progress","tenho me surpreendido com meu progresso"],["this is a study tracker","este é um rastreador de estudos"],["I built it to help students","construí para ajudar estudantes"],["consistency has become my superpower","a constância virou meu superpoder"]],reading:{title:"The Portfolio Presentation",text:"Every candidate needs a good portfolio. Last year, I built a complete one. It has three projects with real results. The first app has reduced load time by 40%. The second has increased user engagement. In the third, I have solved a hard problem with a simple solution. Since then, I have improved the portfolio monthly. My advice: show numbers, not just features. Have you prepared yours?",questions:["What does every candidate need?","How many projects does the portfolio have?","What has the first app reduced?","How often has the writer improved it?","What is the writer's advice?"]},listening:"Listen: 'Every candidate needs a portfolio. Last year I built mine with three projects. The first reduced load time by 40%. Since then, I have improved it monthly. Show numbers, not features!'",speaking:"Grave seu discurso de portfólio: 'This is... I built it to... The result? ... Since then, I have...'"}},{id:21,title:"Semana 21 — First Conditional & Realidade",daysRange:"Dias 140 a 146",subtitle:"Se... Acontecerá, Quando, Assim Que, A Menos Que",badgeClass:"badge-blue",grammar:["If + present, will (situações reais)","When / as soon as / unless / in case","First conditional com modais (can, must, should)","Os 5 erros clássicos do first conditional","Condicionais em cenários de software"],vocab:"Condições, consequências, previsões e regras",reading:"Planos, listas de verificação e cenários de sistema",listening:"Reuniões de planejamento e previsões",speaking:"Planejar a semana e prever resultados",techBridge:"Condicionais de sistemas: 'If the API times out, we will retry'",saturday:{recall:[["if I study daily, I will improve","se eu estudar diariamente, vou melhorar"],["if you don't test, bugs will appear","se você não testar, bugs aparecerão"],["you will pass if you practice","você vai passar se praticar"],["as soon as the tests pass, we will deploy","assim que os testes passarem, implantaremos"],["unless you try, you won't learn","a menos que você tente, não vai aprender"],["in case something fails, we have a backup","caso algo falhe, temos um backup"],["if you pay, you can access","se você pagar, pode acessar"],["if the server fails, we must restart","se o servidor falhar, devemos reiniciar"],["if you have doubts, you should ask","se tiver dúvidas, deveria perguntar"],["if I have time, I will help","se eu tiver tempo, vou ajudar"],["when she arrives, we will start","quando ela chegar, começaremos"],["what will happen if the database goes down?","o que acontecerá se o banco cair?"]],reading:{title:"The Contingency Plan",text:"My team has created a contingency plan. If the payment provider fails, we will switch to the backup. As soon as the alert is detected, the team will be notified. Unless the network is stable, we will work offline. If the client asks for changes, we will estimate the time first. In case of emergency, the manager will decide. When the plan is followed, problems are solved quickly. What happens if you have no plan?",questions:["What happens if the payment provider fails?","When will the team be notified?","What will the team do unless the network is stable?","What will the team do if the client asks for changes?","What is the question at the end?"]},listening:"Listen: 'Contingency plan! If the provider fails, we switch to backup. As soon as the alert is detected, we are notified. Unless the network is stable, we work offline. Plan saves problems!'",speaking:"Crie seu plano B: 'If X happens, I will... As soon as..., I will... Unless..., I will...'"}},{id:22,title:"Semana 22 — Second Conditional & Imaginação",daysRange:"Dias 147 a 153",subtitle:"Hipóteses, Conselhos e Cenários Imaginários",badgeClass:"badge-amber",grammar:["If + past, would (hipotético)","If I were you (conselhos)","Could (capacidade) e might (possibilidade)","Cenários tech hipotéticos (what if?)","Zero conditional para fatos"],vocab:"Sonhos, hipóteses, conselhos e verdades",reading:"Debates de tecnologia e análises de carreira",listening:"Debates e discussões de planos",speaking:"Conselhos, sonhos e debates hipotéticos",techBridge:"'If we rewrote the system, it would be faster' — debates de arquitetura",saturday:{recall:[["if I had more time, I would build","se eu tivesse mais tempo, construiria"],["if I were you, I would practice","se eu fosse você, praticaria"],["if I stopped dreaming, I would stop growing","se eu parasse de sonhar, pararia de crescer"],["if I were you, I would accept","se eu fosse você, aceitaria"],["if I were in your shoes, I'd start early","se estivesse no seu lugar, começaria cedo"],["I wouldn't skip practice","eu não pularia a prática"],["if I spoke English, I could work abroad","se eu falasse inglês, poderia trabalhar fora"],["if I saved money, I might buy a house","se eu poupasse, talvez comprasse uma casa"],["if she invited me, I would go","se ela me convidasse, eu iria"],["if we rewrote the system, it would be faster","se reescrevêssemos o sistema, seria mais rápido"],["what would you do if the client left?","o que você faria se o cliente fosse embora?"],["if you don't take risks, you don't grow","se você não assume riscos, não cresce"]],reading:{title:"The Hypothetical Interview",text:"In my interview practice, I faced a hypothetical question: 'If you were the tech lead, what would you change?' I answered: 'If I were the lead, I would improve the testing process.' Another question: 'What would you do if the client rejected the design?' I said: 'If that happened, I would call a quick meeting to understand the reasons.' These questions test thinking. If I had no practice, I would be nervous. Practice makes hypotheticals feel real.",questions:["What was the first hypothetical question?","What would the writer improve if they were the lead?","What would the writer do if the client rejected the design?","Why are these questions important?","What would happen without practice?"]},listening:"Listen: 'If you were the tech lead, what would you change? I would improve testing. If the client rejected the design, I would call a meeting. Hypothetical questions test thinking. Practice makes them real!'",speaking:"Responda hipotéticos: 'If I were the lead, I would... If that happened, I would...'"}},{id:23,title:"Semana 23 — Voz Passiva Técnica",daysRange:"Dias 154 a 160",subtitle:"Is Made, Was Fixed, Can Be Done",badgeClass:"badge-purple",grammar:["Passiva presente: is/are + particípio","Passiva passada: was/were + particípio","Passiva com modais: can/must/should + be","Passiva em documentações e manuais","Ativa vs passiva: quando usar cada uma"],vocab:"Processos, incidentes, regras e documentação",reading:"Manuais, relatórios de incidente e políticas de segurança",listening:"Relatórios e explicações de processos",speaking:"Descrever processos e relatar incidentes na passiva",techBridge:"Documentação técnica: 'The package is installed with npm', 'Data is stored in the cloud'",saturday:{recall:[["the code is reviewed before deployment","o código é revisado antes do deploy"],["data is stored in the cloud","os dados são armazenados na nuvem"],["the app is built by our team","o app é construído pela nossa equipe"],["the bug was fixed yesterday","o bug foi corrigido ontem"],["three servers were affected","três servidores foram afetados"],["lessons were documented","as lições foram documentadas"],["this task can be done today","esta tarefa pode ser feita hoje"],["the tests must be run before release","os testes devem ser executados antes do release"],["access can be granted with approval","o acesso só pode ser concedido com aprovação"],["the package is installed with npm","o pacote é instalado com npm"],["the database is configured in config.js","o banco é configurado no config.js"],["I designed the new system","eu projetei o novo sistema"]],reading:{title:"The Security Review",text:"Last week, a security review was completed. Many risks were identified and fixed. The passwords were changed for all users. The database was moved to a secure location. Logs are now checked daily. New policies were created and documented. The rules must be followed by everyone. As a result, the system is now much safer. What should be checked in your company?",questions:["What was completed last week?","What were the risks doing?","What was changed for all users?","How often are logs checked now?","What must be followed by everyone?"]},listening:"Listen: 'Last week, a security review was completed. Risks were identified. Passwords were changed. Logs are checked daily. New policies were created. The system is much safer now!'",speaking:"Relate uma revisão na passiva: 'Last week, X was done. Problems were found. The fixes were... Now, X is...'"}}];export{e as d,a as w};
